[ApiController,Authorize(Roles="Administrator,BackOffice")]
[Route("api/phase1/finance/payroll-ready")]
[SubscriptionEntitlement("PayrollReady")]
public sealed class PayrollReadyController(CareDbContext db,ITenantContext tenant,ICurrentUserContext user):ControllerBase
{
 [HttpGet("sources")]public async Task<IActionResult> Sources(CancellationToken t)=>Ok(new{
  runs=await Rows("select r.\"Id\" id,r.\"Period\" period,r.\"GrossPay\" gross_pay,r.\"BranchId\" branch_id from \"PayrollRuns\" r join timesheet_periods p on p.payroll_run_id=r.\"Id\" where r.\"OrganizationId\"=@org and (@wide or r.\"BranchId\"=@branch) and r.\"Status\"='Approved' and p.status='Locked' and not exists(select 1 from finance_payroll_batch_lines b join finance_payroll_lines l on l.id=b.source_id where l.payroll_run_id=r.\"Id\" and not b.released and b.source_type in ('Worked','Travel','TimesheetMileage'))",_=>{},t),
  claims=await Rows("select id,care_worker_id,claim_date,claim_type,amount,currency,branch_id from finance_workforce_claims c where organization_id=@org and (@wide or branch_id=@branch) and status='Approved' and not exists(select 1 from finance_payroll_batch_lines where source_id=c.id and source_type in ('ClaimMileage','ClaimExpense') and not released)",_=>{},t),
  extras=await Rows("select id,care_worker_id,kind,service_date,amount,currency,reference,branch_id from finance_payroll_extras e where organization_id=@org and (@wide or branch_id=@branch) and approved_by is not null and not exists(select 1 from finance_payroll_batch_lines where source_id=e.id and source_type in ('Leave','Adjustment') and not released)",_=>{},t)});
 [HttpGet("batches/{id:guid}/lines")]public async Task<IActionResult> Lines(Guid id,CancellationToken t)=>Ok(await Rows("select l.* from finance_payroll_batch_lines l join finance_payroll_batches b on b.id=l.batch_id where b.id=@id and b.organization_id=@org and (@wide or b.branch_id=@branch) order by l.worker_reference,l.service_date,l.id",c=>Add(c,"id",id),t));
 [HttpGet("contracts")]public async Task<IActionResult> Contracts(CancellationToken t)=>Ok(await Rows("select * from finance_payroll_contracts where organization_id=@org and (@wide or branch_id=@branch) order by created_at desc",_=>{},t));
 [HttpGet("extras")]public async Task<IActionResult> Extras(CancellationToken t)=>Ok(await Rows("select * from finance_payroll_extras where organization_id=@org and (@wide or branch_id=@branch) order by created_at desc",_=>{},t));
 [HttpGet("batches")]public async Task<IActionResult> Batches(CancellationToken t)=>Ok(await Rows("select b.*,c.currency,(select coalesce(sum(amount),0) from finance_payroll_batch_lines where batch_id=b.id and not released) total,(select count(*) from finance_payroll_batch_lines where batch_id=b.id) line_count from finance_payroll_batches b join finance_payroll_contracts c on c.id=b.contract_id where b.organization_id=@org and (@wide or b.branch_id=@branch) order by b.created_at desc",_=>{},t));
 [HttpPost("contracts")]public Task<IActionResult> CreateContract(PayrollExportContractRequest r,CancellationToken t)=>Tx(async()=>
 {
  if(r.RequestId==Guid.Empty||!Scope(r.BranchId)||r.ValidFrom==default||r.ValidTo<r.ValidFrom||string.IsNullOrWhiteSpace(r.Reference)||r.Currency.Length!=3||!r.Currency.All(char.IsAsciiLetter)||r.WorkerMappings.Count==0)return BadRequest(new{message="Contract requires explicit scope, currency, dates, reference, worker payroll references and all pay codes."});
  var snapshot=JsonSerializer.Serialize(r);var replay=await Replay("finance_payroll_contracts",r.RequestId,snapshot,t);if(replay is not null)return replay;
  await Exec("insert into finance_payroll_contracts(id,organization_id,branch_id,reference,currency,valid_from,valid_to,worker_mappings,pay_codes,created_by,request_snapshot) values(@id,@org,@target,@reference,@currency,@start,@end,cast(@workers as jsonb),cast(@codes as jsonb),@actor,cast(@snapshot as jsonb))",c=>{Add(c,"id",r.RequestId);Add(c,"target",r.BranchId);Add(c,"reference",r.Reference.Trim());Add(c,"currency",r.Currency.ToUpperInvariant());Add(c,"start",r.ValidFrom);Add(c,"end",r.ValidTo);Add(c,"workers",JsonSerializer.Serialize(r.WorkerMappings));Add(c,"codes",JsonSerializer.Serialize(r.PayCodes));Add(c,"snapshot",snapshot);},t);await Audit("PAYROLL_CONTRACT_CREATED",r.RequestId,r.BranchId,t);return Created("",new{id=r.RequestId});
 },t);
 [HttpPost("extras")]public Task<IActionResult> CreateExtra(PayrollExtraRequest r,CancellationToken t)=>Tx(async()=>
 {
  if(r.RequestId==Guid.Empty||!Scope(r.BranchId)||r.Kind is not("Leave" or "Adjustment")||r.RoundingMode is not("AwayFromZero" or "ToEven")||r.ServiceDate==default||r.Amount==0||decimal.Round(r.Amount,2)!=r.Amount||r.Currency.Length!=3||!r.Currency.All(char.IsAsciiLetter)||string.IsNullOrWhiteSpace(r.Reference)||string.IsNullOrWhiteSpace(r.Reason))return BadRequest(new{message="An explicit scoped leave/adjustment amount, currency, source, reference and reason are required."});
  var snapshot=JsonSerializer.Serialize(r);var replay=await Replay("finance_payroll_extras",r.RequestId,snapshot,t);if(replay is not null)return replay;
  await Exec("insert into finance_payroll_extras(id,organization_id,branch_id,care_worker_id,kind,service_date,currency,quantity,unit_rate,amount,absence_id,correction_line_id,reference,reason,created_by,request_snapshot,rounding_mode) values(@id,@org,@target,@worker,@kind,@day,@currency,@quantity,@rate,@amount,@absence,@correction,@reference,@reason,@actor,cast(@snapshot as jsonb),@rounding)",c=>{Add(c,"id",r.RequestId);Add(c,"target",r.BranchId);Add(c,"worker",r.CareWorkerId);Add(c,"kind",r.Kind);Add(c,"day",r.ServiceDate);Add(c,"currency",r.Currency.ToUpperInvariant());Add(c,"quantity",r.Quantity);Add(c,"rate",r.UnitRate);Add(c,"amount",r.Amount);NullableGuid(c,"absence",r.AbsenceId);NullableGuid(c,"correction",r.CorrectionLineId);Add(c,"reference",r.Reference.Trim());Add(c,"reason",r.Reason.Trim());Add(c,"snapshot",snapshot);Add(c,"rounding",r.RoundingMode);},t);await Audit("PAYROLL_EXTRA_CREATED",r.RequestId,r.BranchId,t);return Created("",new{id=r.RequestId});
 },t);
 [HttpPost("{kind}/{id:guid}/approve")]public Task<IActionResult> ApproveConfiguration(string kind,Guid id,CancellationToken t)=>Tx(async()=>
 {
  if(kind is not("contracts" or "extras"))return NotFound();var table=kind=="contracts"?"finance_payroll_contracts":"finance_payroll_extras";
  await using var c=await Command($"update {table} set approved_by=@actor,approved_at=now() where id=@id and organization_id=@org and (@wide or branch_id=@branch) and approved_by is null and created_by<>@actor returning branch_id",t);Add(c,"id",id);if(await c.ExecuteScalarAsync(t) is not Guid branch)return Conflict(new{message="An independent person must approve an accessible current draft."});await Audit("PAYROLL_CONFIGURATION_APPROVED",id,branch,t);return Ok(new{id});
 },t);
 [HttpPost("batches")]public Task<IActionResult> CreateBatch(PayrollReadyBatchRequest r,CancellationToken t)=>Tx(async()=>
 {
  if(r.RequestId==Guid.Empty||r.From==default||r.To<r.From||r.To==DateOnly.MaxValue||string.IsNullOrWhiteSpace(r.Reference)||(r.PayrollRunIds.Length>0&&string.IsNullOrWhiteSpace(r.PayrollCurrencyReference)))return BadRequest(new{message="Batch ID, UK dates and reference required. Timesheet payroll needs an explicit reference attesting its source currency matches the approved export contract."});
  var snapshot=JsonSerializer.Serialize(r);var replay=await Replay("finance_payroll_batches",r.RequestId,snapshot,t);if(replay is not null)return replay;
  var contracts=await Rows("select * from finance_payroll_contracts where id=@id and organization_id=@org and (@wide or branch_id=@branch) and approved_by is not null for update",c=>Add(c,"id",r.ContractId),t);if(contracts.Count!=1)return Conflict(new{message="Select an accessible approved export contract."});var contract=contracts[0];var branch=contract.GetProperty("branch_id").GetGuid();var currency=contract.GetProperty("currency").GetString()!;
  await Exec("insert into finance_payroll_batches(id,organization_id,branch_id,contract_id,period_from,period_to,reference,request_snapshot,created_by) values(@id,@org,@target,@contract,@start,@end,@reference,cast(@snapshot as jsonb),@actor)",c=>{Add(c,"id",r.RequestId);Add(c,"target",branch);Add(c,"contract",r.ContractId);Add(c,"start",r.From);Add(c,"end",r.To);Add(c,"reference",r.Reference.Trim());Add(c,"snapshot",snapshot);},t);
  var count=0;
  foreach(var run in r.PayrollRunIds.Distinct())
  {
   var sources=await Rows("""
    select l.*, (v."StartsAt" at time zone 'Europe/London')::date service_date,e.payable_minutes/60 worked_quantity,e.travel_minutes/60 travel_quantity,e.mileage mileage_quantity,e.hourly_rate source_rate,p.travel_rate,p.mileage_rate
    from finance_payroll_lines l join timesheet_entries e on e.id=l.timesheet_entry_id join timesheet_periods p on p.id=e.period_id join "Visits" v on v."Id"=l.visit_id join "PayrollRuns" run on run."Id"=l.payroll_run_id
    where l.payroll_run_id=@run and l.organization_id=@org and l.branch_id=@target and p.status='Locked' and e.status='Approved' and run."Status"='Approved'
    """,c=>{Add(c,"run",run);Add(c,"target",branch);},t);if(sources.Count==0)return Conflict(new{message="A selected run has no approved locked timesheet sources."});
   foreach(var source in sources){var sourceId=source.GetProperty("id").GetGuid();var worker=source.GetProperty("care_worker_id").GetGuid();var day=DateOnly.Parse(source.GetProperty("service_date").GetString()!);var travel=source.GetProperty("travel_amount").GetDecimal();var mileage=source.GetProperty("mileage_amount").GetDecimal();var worked=source.GetProperty("gross_pay").GetDecimal()-travel-mileage;
    foreach(var part in new[]{("Worked",worked,"worked_quantity","source_rate"),("Travel",travel,"travel_quantity","travel_rate"),("TimesheetMileage",mileage,"mileage_quantity","mileage_rate")}){if(part.Item2==0)continue;await Line(r.RequestId,contract,part.Item1,sourceId,worker,day,source.GetProperty(part.Item3).GetDecimal(),source.GetProperty(part.Item4).GetDecimal(),part.Item2,t);count++;}}
  }
  foreach(var id in r.ClaimIds.Distinct())
  {
   var sources=await Rows("select * from finance_workforce_claims where id=@id and organization_id=@org and branch_id=@target and status='Approved' and currency=@currency for update",c=>{Add(c,"id",id);Add(c,"target",branch);Add(c,"currency",currency);},t);if(sources.Count!=1)return Conflict(new{message="A selected claim is missing, unapproved, already paid or has another currency."});var x=sources[0];await Line(r.RequestId,contract,x.GetProperty("claim_type").GetString()=="Mileage"?"ClaimMileage":"ClaimExpense",id,x.GetProperty("care_worker_id").GetGuid(),DateOnly.Parse(x.GetProperty("claim_date").GetString()!),x.GetProperty("quantity").GetDecimal(),x.GetProperty("unit_rate").GetDecimal(),x.GetProperty("amount").GetDecimal(),t);count++;
  }
  foreach(var id in r.ExtraIds.Distinct())
  {
   var sources=await Rows("select * from finance_payroll_extras where id=@id and organization_id=@org and branch_id=@target and approved_by is not null and currency=@currency for update",c=>{Add(c,"id",id);Add(c,"target",branch);Add(c,"currency",currency);},t);if(sources.Count!=1)return Conflict(new{message="A selected extra is missing, unapproved or has another currency."});var x=sources[0];await Line(r.RequestId,contract,x.GetProperty("kind").GetString()!,id,x.GetProperty("care_worker_id").GetGuid(),DateOnly.Parse(x.GetProperty("service_date").GetString()!),x.GetProperty("quantity").GetDecimal(),x.GetProperty("unit_rate").GetDecimal(),x.GetProperty("amount").GetDecimal(),t);count++;
  }
  if(count==0)return Conflict(new{message="Select at least one approved payroll, claim or extra source."});await Audit("PAYROLL_READY_BATCH_SUBMITTED",r.RequestId,branch,t);return Created("",new{id=r.RequestId,lineCount=count});
 },t);
 [HttpPost("batches/{id:guid}/review")]public Task<IActionResult> Review(Guid id,AdjustmentReviewRequest r,CancellationToken t)=>Tx(async()=>
 {
  if(r.Decision is not("Approve" or "Reject")||string.IsNullOrWhiteSpace(r.Reason))return BadRequest();var rows=await Batch(id,t);if(rows.Count!=1)return NotFound();var b=rows[0];var status=r.Decision=="Approve"?"Approved":"Rejected";if(b.GetProperty("status").GetString()!="Submitted")return b.GetProperty("status").GetString()==status&&b.GetProperty("reviewed_by").GetGuid()==user.UserId&&b.GetProperty("review_reason").GetString()==r.Reason.Trim()?Ok(new{id,replayed=true}):Conflict(new{message="Batch already reviewed."});
  await Exec("update finance_payroll_batches set status=@status,reviewed_by=@actor,reviewed_at=now(),review_reason=@reason where id=@id and organization_id=@org",c=>{Add(c,"status",status);Add(c,"reason",r.Reason.Trim());Add(c,"id",id);},t);await Audit("PAYROLL_BATCH_"+status.ToUpperInvariant(),id,b.GetProperty("branch_id").GetGuid(),t);return Ok(new{id,status});
 },t);
 [HttpPost("batches/{id:guid}/confirm-payment")]public Task<IActionResult> Confirm(Guid id,PayrollPaymentConfirmation r,CancellationToken t)=>Tx(async()=>
 {
  if(string.IsNullOrWhiteSpace(r.Reference))return BadRequest(new{message="Actual payment/payroll confirmation reference is required."});var rows=await Batch(id,t);if(rows.Count!=1)return NotFound();var b=rows[0];if(b.GetProperty("status").GetString()=="Paid")return b.GetProperty("payment_reference").GetString()==r.Reference.Trim()?Ok(new{id,replayed=true}):Conflict(new{message="Batch has a different immutable payment reference."});if(b.GetProperty("status").GetString()!="Approved")return Conflict(new{message="Only independently approved batches can be confirmed paid."});await Exec("update finance_payroll_batches set status='Paid',paid_by=@actor,paid_at=now(),payment_reference=@reference where id=@id and organization_id=@org",c=>{Add(c,"id",id);Add(c,"reference",r.Reference.Trim());},t);await Audit("PAYROLL_PAYMENT_CONFIRMED",id,b.GetProperty("branch_id").GetGuid(),t);return Ok(new{id,status="Paid"});
 },t);
 [HttpGet("batches/{id:guid}/export")]public async Task<IActionResult> Export(Guid id,[FromQuery]string format="csv",CancellationToken t=default)
 {
  if(format is not("csv" or "xlsx" or "pdf" or "sage-decimal-hours"))return BadRequest();var batches=await Rows("select * from finance_payroll_batches where id=@id and organization_id=@org and (@wide or branch_id=@branch) and status in ('Approved','Paid')",c=>Add(c,"id",id),t);if(batches.Count!=1)return Conflict(new{message="Export requires an accessible independently approved batch."});var branch=batches[0].GetProperty("branch_id").GetGuid();var grants=await Rows("select * from finance_export_permissions where organization_id=@org and branch_id=@target and user_id=@actor and export_kind='Payroll' and approved_by is not null and (now() at time zone 'Europe/London')::date between valid_from and valid_to order by allow_identifiers desc,allow_rates desc,id",c=>Add(c,"target",branch),t);if(grants.Count==0)return Forbid();var grant=grants[0];
  var records=await Rows("select * from finance_payroll_batch_lines where batch_id=@id and organization_id=@org and not released order by worker_reference,service_date,source_type,id",c=>Add(c,"id",id),t);
  if(format=="sage-decimal-hours")
  {
   if(!grant.GetProperty("allow_identifiers").GetBoolean()||!grant.GetProperty("allow_rates").GetBoolean())return Forbid();
   var columns=new[]{"worker_reference","pay_code","service_date","currency","hours","unit_rate","amount"};
   var rows=records.Select(x=>new object?[]{x.GetProperty("worker_reference").GetString(),x.GetProperty("pay_code").GetString(),x.GetProperty("service_date").GetString(),x.GetProperty("currency").GetString(),decimal.Round(x.GetProperty("quantity").GetDecimal(),2,MidpointRounding.AwayFromZero),x.GetProperty("unit_rate").GetDecimal(),x.GetProperty("amount").GetDecimal()}).ToArray();
   await Audit($"PAYROLL_EXPORT_DOWNLOADED:{format}:grant={grant.GetProperty("id").GetGuid()}:rows={rows.Length}",id,branch,t);
   return File(FinanceExportDocument.Csv(columns,rows),"text/csv",$"sage-payroll-{id}.csv");
  }
  var columnsLegacy=new[]{"id","source_type","source_id","worker_reference","pay_code","service_date","currency","quantity","unit_rate","amount"}.Where(h=>(grant.GetProperty("allow_identifiers").GetBoolean()||h is not("id" or "source_id" or "worker_reference"))&&(grant.GetProperty("allow_rates").GetBoolean()||h is not("unit_rate" or "quantity"))).ToArray();var rowsLegacy=records.Select(x=>columnsLegacy.Select(h=>x.GetProperty(h).ValueKind==JsonValueKind.Number?(object?)x.GetProperty(h).GetDecimal():x.GetProperty(h).GetString()).ToArray()).ToArray();if(format=="pdf"&&!FinanceExportDocument.SupportsPdf(columnsLegacy,rowsLegacy))return UnprocessableEntity(new{message="Select CSV or XLSX to preserve Unicode identifiers."});await Audit($"PAYROLL_EXPORT_DOWNLOADED:{format}:grant={grant.GetProperty("id").GetGuid()}:rows={rowsLegacy.Length}",id,branch,t);
  return format switch{"xlsx"=>File(FinanceExportDocument.Xlsx(columnsLegacy,rowsLegacy),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",$"payroll-{id}.xlsx"),"pdf"=>File(FinanceExportDocument.Pdf($"Payroll {id}",columnsLegacy,rowsLegacy),"application/pdf",$"payroll-{id}.pdf"),_=>File(FinanceExportDocument.Csv(columnsLegacy,rowsLegacy),"text/csv",$"payroll-{id}.csv")};
 }
 async Task Line(Guid batch,JsonElement contract,string kind,Guid source,Guid worker,DateOnly day,decimal quantity,decimal rate,decimal amount,CancellationToken t)
 {
  if(!contract.GetProperty("worker_mappings").TryGetProperty(worker.ToString(),out var mapping)||!contract.GetProperty("pay_codes").TryGetProperty(kind,out var code))throw new Npgsql.PostgresException("Missing explicit worker/pay-code mapping","ERROR","ERROR","23514");
  await Exec("insert into finance_payroll_batch_lines(id,batch_id,organization_id,branch_id,source_type,source_id,care_worker_id,worker_reference,pay_code,service_date,currency,quantity,unit_rate,amount) values(@id,@batch,@org,@target,@kind,@source,@worker,@mapping,@code,@day,@currency,@quantity,@rate,@amount)",c=>{Add(c,"id",Guid.NewGuid());Add(c,"batch",batch);Add(c,"target",contract.GetProperty("branch_id").GetGuid());Add(c,"kind",kind);Add(c,"source",source);Add(c,"worker",worker);Add(c,"mapping",mapping.GetString());Add(c,"code",code.GetString());Add(c,"day",day);Add(c,"currency",contract.GetProperty("currency").GetString());Add(c,"quantity",quantity);Add(c,"rate",rate);Add(c,"amount",amount);},t);
 }
 bool Scope(Guid branch)=>tenant.IsOrganizationWide||branch==tenant.BranchId;
 Task<List<JsonElement>>Batch(Guid id,CancellationToken t)=>Rows("select * from finance_payroll_batches where id=@id and organization_id=@org and (@wide or branch_id=@branch) for update",c=>Add(c,"id",id),t);
 async Task<IActionResult?>Replay(string table,Guid id,string snapshot,CancellationToken t){var rows=await Rows($"select request_snapshot=cast(@snapshot as jsonb) matches from {table} where id=@id and organization_id=@org and (@wide or branch_id=@branch)",c=>{Add(c,"id",id);Add(c,"snapshot",snapshot);},t);return rows.Count==0?null:rows[0].GetProperty("matches").GetBoolean()?Ok(new{id,replayed=true}):Conflict(new{message="Request ID has different details."});}
 async Task<IActionResult>Tx(Func<Task<IActionResult>> work,CancellationToken t){try{return await db.Database.CreateExecutionStrategy().ExecuteAsync(async()=>{await using var tx=await db.Database.BeginTransactionAsync(t);await Exec("select pg_advisory_xact_lock(hashtextextended(@key,0))",c=>Add(c,"key",$"finance-payroll-ready:{tenant.OrganizationId}"),t);var result=await work();if(result is ObjectResult o&&o.StatusCode>=400){await tx.RollbackAsync(t);return result;}await tx.CommitAsync(t);return result;});}catch(Npgsql.PostgresException e)when(e.SqlState is "23514" or "23505" or "23503"){return Conflict(new{message="Payroll source, mapping, currency, approval, duplicate reimbursement or immutable history conflict. Reload the original request before retrying."});}}
 async Task<List<JsonElement>>Rows(string sql,Action<DbCommand>b,CancellationToken t){var rows=new List<JsonElement>();await using var c=await Command($"select row_to_json(q)::text from ({sql})q",t);b(c);await using var r=await c.ExecuteReaderAsync(t);while(await r.ReadAsync(t))rows.Add(JsonSerializer.Deserialize<JsonElement>(r.GetString(0)));return rows;}
 async Task Exec(string sql,Action<DbCommand>b,CancellationToken t){await using var c=await Command(sql,t);b(c);await c.ExecuteNonQueryAsync(t);}
 async Task<DbCommand>Command(string sql,CancellationToken t){var n=db.Database.GetDbConnection();if(n.State!=ConnectionState.Open)await n.OpenAsync(t);var c=n.CreateCommand();c.Transaction=db.Database.CurrentTransaction?.GetDbTransaction();c.CommandText=sql;Add(c,"org",tenant.OrganizationId);Add(c,"branch",tenant.BranchId??Guid.Empty);Add(c,"wide",tenant.IsOrganizationWide);Add(c,"actor",user.UserId);return c;}
 static void Add(DbCommand c,string name,object? value){var p=c.CreateParameter();p.ParameterName=name;p.Value=value??DBNull.Value;c.Parameters.Add(p);}
 static void NullableGuid(DbCommand c,string name,Guid? value){var p=c.CreateParameter();p.ParameterName=name;p.DbType=DbType.Guid;p.Value=(object?)value??DBNull.Value;c.Parameters.Add(p);}
 async Task Audit(string action,Guid id,Guid branch,CancellationToken t){db.AuditEvents.Add(new AuditEvent(Guid.NewGuid(),action,user.UserName,"PayrollReady",id,DateTimeOffset.UtcNow,tenant.OrganizationId,branch));await db.SaveChangesAsync(t);}
}
public sealed record PayrollExportContractRequest(Guid RequestId,Guid BranchId,string Reference,string Currency,DateOnly ValidFrom,DateOnly ValidTo,Dictionary<string,string>WorkerMappings,Dictionary<string,string>PayCodes);
public sealed record PayrollExtraRequest(Guid RequestId,Guid BranchId,Guid CareWorkerId,string Kind,DateOnly ServiceDate,string Currency,decimal Quantity,decimal UnitRate,decimal Amount,Guid? AbsenceId,Guid? CorrectionLineId,string Reference,string Reason,string? RoundingMode=null);
public sealed record PayrollReadyBatchRequest(Guid RequestId,Guid ContractId,DateOnly From,DateOnly To,string Reference,Guid[]PayrollRunIds,Guid[]ClaimIds,Guid[]ExtraIds,string? PayrollCurrencyReference);
public sealed record PayrollPaymentConfirmation(string Reference);
